template<class T> class B { /* Base template class; compiler instantiates a separate version for each T, e.g., B<int>, affecting memory layout as a subobject in derived classes */ };

template<class T> class D : public B<T> { /* Derived template class; inherits from B<T>, enabling implicit pointer conversions like D<T>* to B<T>*, but only for matching T */ };

void f(void* pb);  // Overload for void*; less specific, used when no better match exists
void f(B<int>* pb);  // Overload for B<int>*; more specific due to exact type match

void g(D<int>* p, D<char>* pp, D<double>* ppp) { /* Function using derived pointers; compiler resolves overloads based on static types and conversions */ }
